ee:message.ee:set-payload:
%dw 2.0
output application/json
var formattedPayload = (read(payload.analysis, "application/json"))
---
{
    "sessionId": payload.sessionId,
    "analysis": {
    "dataAndIntegrations": formattedPayload.dataAndIntegrations joinBy " | " default "NA",
    "flowDesign": formattedPayload.flowDesign joinBy " | "  default "NA",
    "errorHandling": formattedPayload.errorHandling joinBy " | "  default "NA",
    "performance": formattedPayload.performance joinBy " | "  default "NA"
}
}

